async def execute(url=""):
    """Granska en webbsida mot SEO- och GEO-kriterier."""
    import json
    import requests

    if not url or not str(url).strip():
        return json.dumps({
            "error": "Missing required argument 'url'",
            "parameter": "url",
            "expected": "an absolute URL, e.g. https://example.se/guider/x",
            "actual": "(empty)",
            "retryable": True,
            "tool_name": "seo_audit_url",
        }, ensure_ascii=False)

    url = str(url).strip()
    if not url.startswith(("http://", "https://")):
        url = "https://" + url

    try:
        resp = requests.get(url, timeout=20, headers={
            "User-Agent": "Mozilla/5.0 (compatible; VertelSEOAudit/1.0)",
            "Accept": "text/html,application/xhtml+xml",
        })
        resp.raise_for_status()
    except Exception as exc:
        return json.dumps({
            "error": "Kunde inte hämta sidan: %s" % exc,
            "url": url,
            "retryable": True,
            "tool_name": "seo_audit_url",
        }, ensure_ascii=False)

    result = env["seo.audit"].audit_html(resp.text, url)
    return json.dumps(result, ensure_ascii=False, indent=2)

async def execute(url=""):
    """Hämta och granska en llms.txt."""
    import json
    import requests

    if not url or not str(url).strip():
        return json.dumps({
            "error": "Missing required argument 'url'",
            "parameter": "url",
            "expected": "a site URL or a full llms.txt URL",
            "actual": "(empty)",
            "retryable": True,
            "tool_name": "seo_llms_txt",
        }, ensure_ascii=False)

    url = str(url).strip().rstrip("/")
    if not url.startswith(("http://", "https://")):
        url = "https://" + url
    if not url.endswith("llms.txt"):
        url = url + "/llms.txt"

    try:
        resp = requests.get(url, timeout=20, headers={
            "User-Agent": "Mozilla/5.0 (compatible; VertelSEOAudit/1.0)",
        })
        if resp.status_code == 404:
            return json.dumps({
                "error": "Ingen llms.txt finns på %s" % url,
                "hint": "Skapa /llms.txt enligt llmstxt.org — se skillen llms-txt.",
                "tool_name": "seo_llms_txt",
            }, ensure_ascii=False)
        resp.raise_for_status()
    except Exception as exc:
        return json.dumps({
            "error": "Kunde inte hämta %s: %s" % (url, exc),
            "retryable": True,
            "tool_name": "seo_llms_txt",
        }, ensure_ascii=False)

    result = env["seo.audit"].audit_llms_txt(resp.text)
    result["url"] = url
    result["bytes"] = len(resp.text)
    return json.dumps(result, ensure_ascii=False, indent=2)

async def execute(raw=""): """Validera en JSON-LD-sträng.""" import json
if not raw or not str(raw).strip(): return json.dumps({ "error": "Missing required argument 'raw'", "parameter": "raw", "expected": "a JSON-LD string", "actual": "(empty)", "retryable": True, "tool_name": "seo_json_ld_check", }, ensure_ascii=False)
result = env["seo.audit"].audit_json_ld(str(raw)) return json.dumps(result, ensure_ascii=False, indent=2)
